export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.setRenderingAutoClearDepthStencil(1, false, true, false);

  const camera = new BABYLON.ArcRotateCamera("camera", -0.8, 1.239, 9.37, new BABYLON.Vector3(0, 1, 0));
  camera.lowerRadiusLimit = 1;
  camera.upperRadiusLimit = 12;
  camera.upperBetaLimit = 1.59;

  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.1;
  camera.panningSensibility = 0;

  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0.5, 1, 0), scene);

  BABYLON.SceneLoader.ImportMeshAsync(
    "",
    "https://raw.githubusercontent.com/CedricGuillemet/dump/master/CharController/",
    "levelTest.glb",
    scene
  ).then(() => {
    var lightmap = new BABYLON.Texture("https://raw.githubusercontent.com/CedricGuillemet/dump/master/CharController/lightmap.jpg");
    var lightmapped = ["level_primitive0", "level_primitive1", "level_primitive2"];
    lightmapped.forEach((meshName) => {
      var mesh = scene.getMeshByName(meshName);
      mesh.isPickable = false;
      mesh.material.lightmapTexture = lightmap;
      mesh.material.useLightmapAsShadowmap = true;
      mesh.material.lightmapTexture.uAng = Math.PI;
      mesh.material.lightmapTexture.level = 1.6;
      mesh.material.lightmapTexture.coordinatesIndex = 1;
      mesh.freezeWorldMatrix();
      mesh.doNotSyncBoundingInfo = true;
    });
  });

  let selectedMesh = null;
  let selectedVertex = null;
  let vertexSpheres = [];

  const gizmoManager = new BABYLON.GizmoManager(scene);
  gizmoManager.usePointerToAttachGizmos = false;

  const highlightLayer = new BABYLON.HighlightLayer("hl", scene, {
    isStroke: true,
    mainTextureRatio: 1,
    blurVerticalSize: 0.5,
    blurHorizontalSize: 0.5,
  });
  highlightLayer.innerGlow = false;

  const box = BABYLON.MeshBuilder.CreateBox("box", { size: 1.5 }, scene);
  box.position = new BABYLON.Vector3(14, 0.1, -11);
  box.isPickable = true;

  camera.setTarget(box.position.clone());
  camera.alpha = -0.8;
  camera.beta = 1.239;
  camera.radius = 9.37;

  const dynamicTexture = new BABYLON.DynamicTexture("dynamic texture", { width: 512, height: 256 }, scene, false);
  dynamicTexture.hasAlpha = true;
  dynamicTexture.drawText("vertex snapping", null, 140, "bold 48px Arial", "white", "orange", true);

  const textMaterial = new BABYLON.PBRMaterial("textMat", scene);
  textMaterial.metallic = 0;
  textMaterial.albedoTexture = dynamicTexture;
  textMaterial.backFaceCulling = false;
  textMaterial.directIntensity = 2;
  box.material = textMaterial;

  selectedMesh = box;
  highlightLayer.addMesh(selectedMesh, new BABYLON.Color3(0.63, 0.24, 1));

  gizmoManager.positionGizmoEnabled = true;
  gizmoManager.attachToMesh(selectedMesh);

  const previewSphere = BABYLON.MeshBuilder.CreateBox("previewSphere", { size: 0.1 }, scene);
  previewSphere.isVisible = false;
  previewSphere.material = new BABYLON.StandardMaterial("previewMat", scene);
  previewSphere.material.diffuseColor = new BABYLON.Color3(1, 0, 0);
  previewSphere.renderingGroupId = 1;
  previewSphere.visibility = 0.5;
  highlightLayer.addExcludedMesh(previewSphere);

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type !== BABYLON.PointerEventTypes.POINTERPICK) return;

    const pickInfo = pointerInfo.pickInfo;
    if (!pickInfo || !pickInfo.hit) return;

    const pickedMesh = pickInfo.pickedMesh;
    const pickedPoint = pickInfo.pickedPoint;
    if (!pickedMesh || !pickedPoint) return;

    const isHelperSphere = pickedMesh.name.startsWith("vSphere");
    const hasMetadata = pickedMesh.metadata && pickedMesh.metadata.localPos;

    if (selectedMesh && !selectedVertex && pickedMesh !== selectedMesh && pickedMesh !== previewSphere) {
      selectedVertex = null;
      dragStartWorldVertexPos = null;
      dragStartRootPos = null;
      previewSphere.isVisible = false;
      return;
    }

    if (!selectedMesh) {
      // 1단계: 첫 번째 클릭 - mesh 선택
      selectedMesh = isHelperSphere && hasMetadata ? pickedMesh.metadata.sourceMesh : pickedMesh;
      // highlightLayer.addMesh(selectedMesh, new BABYLON.Color3(1, 0.61, 0.24));
      highlightLayer.addMesh(selectedMesh, new BABYLON.Color3(0.63, 0.24, 1));

      gizmoManager.attachToMesh(selectedMesh);
    } else if (!selectedVertex) {
      if (selectedMesh === pickedMesh) {
        cleanup();
        return;
      }
      // 2단계: 두 번째 클릭 - vertex 선택
      const helperSource = hasMetadata ? pickedMesh.metadata.sourceMesh : null;
      if (isHelperSphere && hasMetadata && getRootTransformNode(helperSource) === getRootTransformNode(selectedMesh)) {
        selectedVertex = {
          index: pickedMesh.metadata.vertexIndex,
          localPos: pickedMesh.metadata.localPos,
          worldPos: pickedMesh.metadata.worldPos,
        };
        previewSphere.material.diffuseColor = new BABYLON.Color3(0, 0.4, 1);
        previewSphere.position.copyFrom(selectedVertex.worldPos);
        previewSphere.isVisible = true;
      } else {
        gizmoManager.attachToMesh(null);

        selectedVertex = getClosestVertexToPoint(selectedMesh, pickedPoint);
        if (selectedVertex) {
          previewSphere.material.diffuseColor = new BABYLON.Color3(0, 0.4, 1);
          previewSphere.position.copyFrom(selectedVertex.worldPos);
          previewSphere.isVisible = true;
        }
      }
    } else {
      // 3단계: 최종 클릭 → 정렬
      const worldMatrix = selectedMesh.getWorldMatrix();
      const currentVertexWorldPos = BABYLON.Vector3.TransformCoordinates(selectedVertex.localPos, worldMatrix);
      const offset = pickedPoint.subtract(currentVertexWorldPos);

      const root = getRootTransformNode(selectedMesh);
      root.position.addInPlace(offset);

      cleanup();
    }
  });

  // 마우스 이동 미리보기
  let dragStartWorldVertexPos = null;
  let dragStartRootPos = null;

  scene.onBeforeRenderObservable.add(() => {
    const pickInfo = scene.pick(scene.pointerX, scene.pointerY, () => true);
    if (!pickInfo || !pickInfo.hit || !pickInfo.pickedPoint || pickInfo.pickedMesh === previewSphere) return;

    const point = pickInfo.pickedPoint;

    if (selectedMesh && selectedVertex) {
      const root = getRootTransformNode(selectedMesh);

      if (!dragStartWorldVertexPos || !dragStartRootPos) {
        const worldMatrix = selectedMesh.getWorldMatrix();
        dragStartWorldVertexPos = BABYLON.Vector3.TransformCoordinates(selectedVertex.localPos, worldMatrix);
        dragStartRootPos = root.position.clone();
      }

      const offset = point.subtract(dragStartWorldVertexPos);
      root.position = dragStartRootPos.add(offset);

      selectedVertex.worldPos = point.clone();
      previewSphere.position.copyFrom(point);
    } else {
      dragStartWorldVertexPos = null;
      dragStartRootPos = null;

      if (selectedMesh) {
        const closest = getClosestVertexToPoint(selectedMesh, point);
        if (closest) {
          previewSphere.material.diffuseColor = new BABYLON.Color3(1, 0, 0);
          previewSphere.position.copyFrom(closest.worldPos);
          previewSphere.isVisible = true;
        } else {
          previewSphere.isVisible = false;
        }
      }
    }
  });

  function cleanupVertexSpheres() {
    vertexSpheres.forEach((s) => s.dispose());
    vertexSpheres = [];
  }

  function cleanup() {
    selectedMesh = null;
    selectedVertex = null;
    highlightLayer.removeAllMeshes();
    cleanupVertexSpheres();
    dragStartWorldVertexPos = null;
    dragStartRootPos = null;
    previewSphere.material.diffuseColor = new BABYLON.Color3(1, 0, 0);
    previewSphere.isVisible = false;
  }

  function getClosestVertexToPoint(mesh, point) {
    const positions = mesh.getVerticesData(BABYLON.VertexBuffer.PositionKind);
    const worldMatrix = mesh.getWorldMatrix();

    let closest = { index: -1, worldPos: null, localPos: null };
    let minDist = Infinity;

    for (let i = 0; i < positions.length; i += 3) {
      const local = new BABYLON.Vector3(positions[i], positions[i + 1], positions[i + 2]);
      const world = BABYLON.Vector3.TransformCoordinates(local, worldMatrix);
      const dist = BABYLON.Vector3.Distance(world, point);
      if (dist < minDist) {
        minDist = dist;
        closest = {
          index: i / 3,
          localPos: local,
          worldPos: world,
        };
      }
    }
    return closest.index === -1 ? null : closest;
  }

  function getRootTransformNode(mesh) {
    let current = mesh;
    while (current.parent) {
      current = current.parent;
    }
    return current;
  }

  return scene;
}
